 "content": "def transform(grid):
    """On each column marked by a bottom 5, extend each seed vertically.

    Empty cells between seeds take the color of the next seed below; cells
    above the first seed take its color. The original nonzero seeds remain.
    """
    out = [row[:] for row in grid]
    if not out:
        return out
    h, w = len(out), len(out[0])
    for c in range(w):
        if out[h - 1][c] != 5:
            continue
        seeds = [(r, out[r][c]) for r in range(h) if out[r][c] != 0]
        if not seeds:
            continue
        for r in range(h):
            if out[r][c] != 0:
                continue
            below = next(((sr, color) for sr, color in seeds if sr > r), None)
            out[r][c] = below[1] if below is not None else seeds[-1][1]
    return out

if __name__ == "__main__":
    pass
